import {useState} from 'react';
import './App.css';

function App(){
  const [todos,setTodos] = useState([]);
  const [inputValue,setInputValue] = useState('');

  const addTodo = () => {
    if (inputValue.trim() !== ''){
      setTodos([...todos, {
        id:Date.now(),
        text:inputValue,
        completed:false
      }]);
      setInputValue('');
    }
  };
  const handleKeypress = (e) =>{
    if (e.key === 'Enter'){
      addTodo();
    }
  };

  const deleteTodo = (id) => {
    setTodos(todos.filter(todo => todo.id !== id));
  };

}
